static void hr(HRESULT result,const char* operation){
    if(FAILED(result))throw std::runtime_error(QString("%1: HRESULT 0x%2").arg(operation).arg(unsigned(result),8,16,QChar('0')).toStdString());
}
static double val(QJsonObject object,const char* key,double fallback=0){return object.value(key).toDouble(fallback);}
static void saveJson(const QString& path,const QJsonObject& object){
    auto bytes=QJsonDocument(object).toJson(QJsonDocument::Compact);
    // An antivirus/status reader can briefly hold the old file without delete
    // sharing on Windows. Retry publication, never replace atomics with a
    // truncate-and-write status that another process could observe half-written.
    for(int attempt=0;attempt<20;attempt++){
        QSaveFile file(path);
        if(file.open(QIODevice::WriteOnly)&&file.write(bytes)==bytes.size()&&file.commit())return;
        Sleep(5);
    }
    throw std::runtime_error("Cannot publish export status");
}
