 float3 weights=extra.x>.5?float3(.2126,.7152,.0722):float3(.299,.587,.114);
 const float kernel[5]={1,4,6,4,1};float blurred=0;float4 c=samplePixel(v.uv);
 for(int y=-2;y<=2;y++)for(int x=-2;x<=2;x++)blurred+=dot(samplePixel(v.uv+float2(x,y)*direction.xy).rgb,weights)*kernel[x+2]*kernel[y+2]/256;
 float luma=dot(c.rgb,weights),delta=(luma-blurred)*extra.y;
