            auto bytes=fwrite(lock.bitstreamBufferPtr,1,lock.bitstreamSizeInBytes,file);auto expected=lock.bitstreamSizeInBytes;api.nvEncUnlockBitstream(encoder,bitstream);
            if(bytes!=expected)throw std::runtime_error("Disk write failed during export");
